  "teller":{"steps":[{"e":"🏦","t":"Đọc giới thiệu rồi bấm Vào việc thôi!","s":["[data-command=\"tl_intro\"]"],"o":1},{"e":"🎓","t":"Học ba bài ngắn: đọc rồi chọn đáp án đúng.","s":[".tl-learn .tl-options"],"o":1,"d":"Ứng tuyển ở phòng giao dịch Bến Chợ (mở từ chương 3). Học ba bài ngắn, thi thực hành ba phần, rồi hai ca có chị Hạnh kèm."},{"e":"📝","t":"Bấm Bắt đầu thi thực hành, làm đủ ba phần.","k":["Bắt đầu thi thực hành"],"s":[".tl-exam-go"],"v":{"t":"Học nốt các bài với chị Hạnh trước.","s":[".tl-learn .tl-options"]},"o":1,"d":"Ứng tuyển ở phòng giao dịch Bến Chợ (mở từ chương 3). Học ba bài ngắn, thi thực hành ba phần, rồi hai ca có chị Hạnh kèm."},{"e":"⏱️","t":"Mỗi phần thi làm một lần. Bí thì Gợi ý, mất 🎯.","s":[".tl-exam:has(.tl-timer)"],"o":1,"d":"Ứng tuyển ở phòng giao dịch Bến Chợ (mở từ chương 3). Học ba bài ngắn, thi thực hành ba phần, rồi hai ca có chị Hạnh kèm."},{"e":"💼","t":"Đầu ca: đếm quỹ rồi so với sổ bàn giao.","s":[".tl-shift"],"o":1,"d":"Đầu ca: đếm quỹ, so sổ bàn giao, khớp thì ký nhận, lệch thì lập biên bản."},{"e":"🙋","t":"Bấm Nhận yêu cầu để mời khách.","k":["Nhận yêu cầu"],"s":[".sk-ask","[data-command=\"ask\"]"],"v":{"t":"Làm xong phần đang mở ở trên trước.","h":1,"s":[".tl-learn .tl-options",".tl-exam",".tl-shift"]},"w":"Nút hiện khi có khách mới.","d":"Mỗi khách: nhận yêu cầu, kiểm tra thông tin, xử lý tiền, xác nhận, giao biên nhận."},{"e":"🧾","t":"Đọc phiếu, làm từng bước trên thẻ.","s":[".tl-step"],"d":"Mỗi khách: nhận yêu cầu, kiểm tra thông tin, xử lý tiền, xác nhận, giao biên nhận."},{"e":"💵","t":"Kéo hoặc chạm tờ tiền vào khay cho đúng số.","s":[".tl-tray"],"o":1,"d":"Khay tiền tự cộng: sai thì bỏ bớt, sửa xong mới xác nhận."},{"e":"✅","t":"Khay khớp phiếu thì bấm Xác nhận khay tiền.","k":["Xác nhận khay tiền"],"s":[".tl-tray-send"],"o":1,"d":"Khay tiền tự cộng: sai thì bỏ bớt, sửa xong mới xác nhận."},{"e":"🧾","t":"Cuối ca: bàn giao quỹ, khớp từng biên nhận.","s":[".tl-close > summary"],"x":1}]},
